{
    UserBack myUser;
    if (!IsAuth(out myUser))
        return new List<Task>().AsQueryable();
    try
    {

        if (myUser.IsSystemManager==true)
        {
            return _db.Context.Tasks.Where(e => e.MainUserId == myUser.MainUserId);
        }
        if (myUser.IsFilialManager==true)
        {
            string Filial = myUser.Filial;
            return _db.Context.Tasks.Where(e => e.Filial==Filial && e.MainUserId == myUser.MainUserId);

        }
        if (myUser.IsClientManager==true)
        {
            string Client = myUser.Client ;
            string[] Clients = Client.Split(',');
           // List<Task> mytasks = _db.Context.Tasks.Where(e => Clients.Contains(e.Client) && e.MainUserId == myUser.MainUserId).ToList();
            return _db.Context.Tasks.Where(e => Clients.Contains(e.Client) && e.MainUserId == myUser.MainUserId);
        }
        else
        {
            string MemberId = myUser.Id.ToString();

            List<Job> myList = _db.Context.Jobs.Where(e => e.MemberId == MemberId).ToList();
            List<int> ids=new List<int>();
            foreach (var job in myList)
            {
                ids.Add((int)job.ParentId);
            }
           // List<Task> myl = _db.Context.Tasks.Where(e => ids.Contains(e.Id)).ToList();
            return _db.Context.Tasks.Where(e => ids.Contains(e.Id) && e.MainUserId == myUser.MainUserId);



        }
    }
    catch (Exception em)
    {
        return new List<Task>().AsQueryable();
